-- Name: donate_shards_to_group(uuid, uuid, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.donate_shards_to_group(p_group_id uuid, p_user_id uuid, p_amount integer, p_expires_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_user_id THEN
        RAISE EXCEPTION 'Not authorized';
    END IF;

    UPDATE public.users SET personal_shards = personal_shards - p_amount
    WHERE id = p_user_id AND personal_shards >= p_amount;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Insufficient shards';
    END IF;

    INSERT INTO public.shard_ledger (user_id, delta, reason, reference_id)
    VALUES (p_user_id, -p_amount, 'group_donation', p_group_id);

    INSERT INTO public.group_shard_contributions (group_id, user_id, shards_contributed, expires_at)
    VALUES (p_group_id, p_user_id, p_amount, p_expires_at);
END;
$$;


--

-- Name: grant_preshards(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_preshards(p_user_id uuid, p_amount integer, p_reason text DEFAULT 'admin_grant'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    UPDATE public.users SET preshards = preshards + p_amount
    WHERE id = p_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'User not found: %', p_user_id;
    END IF;

    INSERT INTO public.preshard_ledger (user_id, delta, reason, reference_id)
    VALUES (p_user_id, p_amount, p_reason, NULL);
END;
$$;


--

-- Name: grant_shards(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_shards(p_user_id uuid, p_amount integer, p_reason text DEFAULT 'admin_grant'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    UPDATE public.users SET personal_shards = personal_shards + p_amount
    WHERE id = p_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'User not found: %', p_user_id;
    END IF;

    INSERT INTO public.shard_ledger (user_id, delta, reason, reference_id)
    VALUES (p_user_id, p_amount, p_reason, NULL);
END;
$$;


